import sys
import os
import datetime
import re
import hashlib
import curses

VERSION = "calcurse 4.8.2 -- text-based organizer\n\nCopyright (c) 2004-2023 calcurse Development Team.\nThis is free software; see the source for copying conditions."

HELP_TEXT = """Usage:
