Submit bug reports to <bugs@calcurse.org>."""

def parse_date(date_str):
    if date_str == 'today':
        return datetime.datetime.now().replace(hour=0, minute=0, second=0, microsecond=0)
    if date_str == 'tomorrow':
        return (datetime.datetime.now() + datetime.timedelta(days=1)).replace(hour=0, minute=0, second=0, microsecond=0)
    if date_str == 'yesterday':
        return (datetime.datetime.now() - datetime.timedelta(days=1)).replace(hour=0, minute=0, second=0, microsecond=0)
    try:
        return datetime.datetime.strptime(date_str, "%m/%d/%Y")
    except:
        return None

class Calcurse:
    def __init__(self, datadir, confdir, calendar_file=None):
        self.datadir = os.path.abspath(datadir)
        self.confdir = os.path.abspath(confdir)
        self.calendar_file = calendar_file or os.path.join(self.datadir, 'apts')
        self.todo_file = os.path.join(self.datadir, 'todo')
        self.notes_dir = os.path.join(self.datadir, 'notes')
        self.conf_file = os.path.join(self.confdir, 'conf')

        os.makedirs(self.datadir, exist_ok=True)
        os.makedirs(self.confdir, exist_ok=True)
        os.makedirs(self.notes_dir, exist_ok=True)

        self.appointments = []
        self.todos = []
        self.load_data()

    def load_data(self):
        if os.path.exists(self.calendar_file):
            with open(self.calendar_file, 'r') as f:
                for line in f:
                    self.parse_apt_line(line.strip())
        if os.path.exists(self.todo_file):
            with open(self.todo_file, 'r') as f:
                for line in f:
                    self.parse_todo_line(line.strip())

    def parse_apt_line(self, line):
        m = re.match(r'^(\d{2}/\d{2}/\d{4}) @ (\d{2}:\d{2}) -> (\d{2}/\d{2}/\d{4}) @ (\d{2}:\d{2})(.*)\|(.*)$', line)
        if m:
            start_date_str, start_time_str, end_date_str, end_time_str, extra, desc = m.groups()
            recurrence = None
            note = None
            if '{' in extra:
                recur_match = re.search(r'\{(.*?)\}', extra)
                if recur_match:
                    recurrence = recur_match.group(1)
            if '>' in extra:
                note_match = re.search(r'>(.*?)($| )', extra)
                if note_match:
                    note = note_match.group(1).strip()
            self.appointments.append({
                'type': 'appointment',
                'start': datetime.datetime.strptime(f"{start_date_str} {start_time_str}", "%m/%d/%Y %H:%M"),
                'end': datetime.datetime.strptime(f"{end_date_str} {end_time_str}", "%m/%d/%Y %H:%M"),
                'recurrence': recurrence,
                'note': note,
                'description': desc.strip(),
                'raw': line
            })
        else:
            m = re.match(r'^(\d{2}/\d{2}/\d{4}) \[(\d+)\](.*)$', line)
            if m:
                date_str, item_id, rest = m.groups()
                recurrence = None
                note = None
                desc = rest
                if '{' in rest:
                    recur_match = re.search(r'\{(.*?)\}', rest)
                    if recur_match:
                        recurrence = recur_match.group(1)
                        desc = desc.replace(recur_match.group(0), '')
                if '>' in rest:
                    note_match = re.search(r'>(.*?)($| )', rest)
                    if note_match:
                        note = note_match.group(1).strip()
                        desc = desc.replace(note_match.group(0), '')
                self.appointments.append({
                    'type': 'event',
                    'date': datetime.datetime.strptime(date_str, "%m/%d/%Y"),
                    'id': int(item_id),
                    'recurrence': recurrence,
                    'note': note,
                    'description': desc.strip(),
                    'raw': line
                })

    def parse_todo_line(self, line):
        m = re.match(r'^\[(\d+)\](.*)$', line)
        if m:
            priority, rest = m.groups()
            note = None
            desc = rest
            if '>' in rest:
                note_match = re.search(r'>(.*?)($| )', rest)
                if note_match:
                    note = note_match.group(1).strip()
                    desc = desc.replace(note_match.group(0), '')
            self.todos.append({
                'priority': int(priority),
                'note': note,
                'description': desc.strip(),
                'raw': line
            })

    def is_occurring_on(self, item, day):
        if item['type'] == 'appointment':
            start_day = item['start'].replace(hour=0, minute=0, second=0, microsecond=0)
            if item['recurrence']:
                period, end_date_str = item['recurrence'].split(' -> ')
                end_date = datetime.datetime.strptime(end_date_str, "%m/%d/%Y")
                if day < start_day or day > end_date:
                    return False
                num = int(period[:-1])
                unit = period[-1]
                if unit == 'D':
                    return (day - start_day).days % num == 0
                if unit == 'W':
                    return (day - start_day).days % (num * 7) == 0
                if unit == 'M':
                    if day.day != start_day.day: return False
                    months = (day.year - start_day.year) * 12 + (day.month - start_day.month)
                    return months % num == 0
                if unit == 'Y':
                    if (day.month, day.day) != (start_day.month, start_day.day): return False
                    return (day.year - start_day.year) % num == 0
                return False
            else:
                return start_day == day
        elif item['type'] == 'event':
            start_day = item['date']
            if item['recurrence']:
                period, end_date_str = item['recurrence'].split(' -> ')
                end_date = datetime.datetime.strptime(end_date_str, "%m/%d/%Y")
                if day < start_day or day > end_date:
                    return False
                num = int(period[:-1])
                unit = period[-1]
                if unit == 'D':
                    return (day - start_day).days % num == 0
                if unit == 'W':
                    return (day - start_day).days % (num * 7) == 0
                if unit == 'M':
                    if day.day != start_day.day: return False
                    months = (day.year - start_day.year) * 12 + (day.month - start_day.month)
                    return months % num == 0
                if unit == 'Y':
                    if (day.month, day.day) != (start_day.month, start_day.day): return False
                    return (day.year - start_day.year) % num == 0
                return False
            else:
                return start_day == day
        return False

    def get_items_for_day(self, day):
        day_items = []
        for apt in self.appointments:
            if self.is_occurring_on(apt, day):
                day_items.append(apt)
        return day_items

def export_ical(cal):
    print("BEGIN:VCALENDAR")
    print("VERSION:2.0")
    print("PRODID:-//calcurse//NONSGML v4.8.2//EN")
    # Appointments and events
    for a in cal.appointments:
        print("BEGIN:VEVENT")
        if a['type'] == 'appointment':
            print(f"DTSTART:{a['start'].strftime('%Y%m%dT%H%M%S')}")
            duration = a['end'] - a['start']
            h, rem = divmod(duration.seconds, 3600)
            m, s = divmod(rem, 60)
            print(f"DURATION:P{duration.days}DT{h}H{m}M{s}S")
        else:
            print(f"DTSTART;VALUE=DATE:{a['date'].strftime('%Y%m%d')}")

        if a['recurrence']:
            period, end_date_str = a['recurrence'].split(' -> ')
            num = int(period[:-1])
            unit = period[-1]
            freq = {'D': 'DAILY', 'W': 'WEEKLY', 'M': 'MONTHLY', 'Y': 'YEARLY'}[unit]
            until = datetime.datetime.strptime(end_date_str, "%m/%d/%Y")
            if a['type'] == 'appointment':
                # For appointments, UNTIL should include time?
                # Actually calcurse output: UNTIL=20231028T120000
                until_str = until.strftime('%Y%m%dT%H%M%S') # Wait, should use start time?
                if a['type'] == 'appointment':
                    until_str = until.replace(hour=a['start'].hour, minute=a['start'].minute).strftime('%Y%m%dT%H%M%S')
            else:
                until_str = until.strftime('%Y%m%d')
            print(f"RRULE:FREQ={freq};UNTIL={until_str}") # simplified, should handle interval

        print(f"SUMMARY:{a['description']}")
        print("END:VEVENT")

    # Todos
    for t in cal.todos:
        print("BEGIN:VTODO")
        print(f"PRIORITY:{t['priority']}")
        print(f"SUMMARY:{t['description']}")
        print("END:VTODO")
    print("END:VCALENDAR")

def run_tui(cal):
    # Very basic TUI placeholder
    def tui(stdscr):
        curses.curs_set(0)
        stdscr.clear()
        while True:
            stdscr.addstr(0, 0, "calcurse TUI - Press 'q' to quit (Placeholder)")
            stdscr.refresh()
            c = stdscr.getch()
            if c == ord('q'):
                break
    curses.wrapper(tui)

def main():
    args = sys.argv[1:]
    if not args:
        # TUI mode
        datadir = os.path.expanduser('~/.local/share/calcurse')
        confdir = os.path.expanduser('~/.config/calcurse')
        if os.path.exists(os.path.expanduser('~/.calcurse')):
            datadir = os.path.expanduser('~/.calcurse')
            confdir = os.path.expanduser('~/.calcurse')
        cal = Calcurse(datadir, confdir)
        run_tui(cal)
        return

    if '-v' in args or '--version' in args:
        print(VERSION)
        return
    if '-h' in args or '--help' in args:
        print(HELP_TEXT)
        return

    datadir = os.path.expanduser('~/.local/share/calcurse')
    confdir = os.path.expanduser('~/.config/calcurse')
    if os.path.exists(os.path.expanduser('~/.calcurse')):
        datadir = os.path.expanduser('~/.calcurse')
        confdir = os.path.expanduser('~/.calcurse')

    calendar_file = None
    i = 0
    while i < len(args):
        if args[i] == '-D':
            datadir = args[i+1]
            i += 2
        elif args[i] == '-C':
            confdir = args[i+1]
            i += 2
        elif args[i] == '-c':
            calendar_file = args[i+1]
            i += 2
        else:
            i += 1

    cal = Calcurse(datadir, confdir, calendar_file)

    if '-G' in args:
        filter_type = None
        if '--filter-type' in args:
            idx = args.index('--filter-type')
            filter_type = args[idx+1]

        # In -G mode, todos are printed first
        if filter_type is None or filter_type == 'todo':
            for t in sorted(cal.todos, key=lambda x: (x['priority'], x['description'])):
                print(t['raw'])

        if filter_type is None or filter_type == 'apt':
            # Appointments/events are printed in some order?
            # From my tests, it seemed a bit mixed. Let's just print them.
            for a in cal.appointments:
                print(a['raw'])
        return

    if '-x' in args or any(a.startswith('-x') for a in args):
        export_ical(cal)
        return

    # Handle queries -a, -d, -Q
    query_days = 0
    start_date = None
    if '-a' in args:
        start_date = datetime.datetime.now().replace(hour=0, minute=0, second=0, microsecond=0)
        query_days = 1
    elif '-d' in args:
        idx = args.index('-d')
        val = args[idx+1]
        start_date = parse_date(val)
        if start_date is None:
            try:
                query_days = int(val)
                start_date = datetime.datetime.now().replace(hour=0, minute=0, second=0, microsecond=0)
            except:
                print(f"args.c: 550: invalid date: {val}")
                sys.exit(1)
        else:
            query_days = 1
    elif '-Q' in args:
        start_date = datetime.datetime.now().replace(hour=0, minute=0, second=0, microsecond=0)
        end_date = None
        if '--from' in args:
            idx = args.index('--from')
            start_date = parse_date(args[idx+1])
        if '--to' in args:
            idx = args.index('--to')
            end_date = parse_date(args[idx+1])
        if '--days' in args:
            idx = args.index('--days')
            query_days = int(args[idx+1])

        if end_date:
            query_days = (end_date - start_date).days + 1
        elif query_days == 0:
            query_days = 1

    if start_date:
        # Print todos for -Q
        if '-Q' in args:
            if cal.todos:
                print("to do:")
                for t in sorted(cal.todos, key=lambda x: (x['priority'], x['description'])):
                    print(f"{t['priority']}. {t['description']}")
                print()

        for d in range(query_days):
            day = start_date + datetime.timedelta(days=d)
            items = cal.get_items_for_day(day)
            if items:
                print(day.strftime("%m/%d/%y:"))
                events = sorted([i for i in items if i['type'] == 'event'], key=lambda x: (x['id'], x['description']))
                apts = sorted([i for i in items if i['type'] == 'appointment'], key=lambda x: (x['start'], x['description']))
                for e in events:
                    print(f" * {e['description']}")
                for a in apts:
                    print(f" - {a['start'].strftime('%H:%M')} -> {a['end'].strftime('%H:%M')}")
                    print(f"\t{a['description']}")
                if d < query_days - 1:
                    print()

    # Handle -t
    for arg in args:
        if arg.startswith('-t'):
            priority = None
            if len(arg) > 2:
                priority = int(arg[2:])

            todos = cal.todos
            if priority is not None:
                todos = [t for t in todos if t['priority'] == priority]

            if todos:
                print("to do:")
                for t in sorted(todos, key=lambda x: (x['priority'], x['description'])):
                    print(f"{t['priority']}. {t['description']}")

if __name__ == "__main__":
    main()
EOF
"}

