def parse_date(date_str):
    if date_str == 'today':
        return datetime.datetime.now().replace(hour=0, minute=0, second=0, microsecond=0)
    if date_str == 'tomorrow':
        return (datetime.datetime.now() + datetime.timedelta(days=1)).replace(hour=0, minute=0, second=0, microsecond=0)
    if date_str == 'yesterday':
        return (datetime.datetime.now() - datetime.timedelta(days=1)).replace(hour=0, minute=0, second=0, microsecond=0)
    for fmt in ("%m/%d/%Y", "%m/%d/%y"):
        try:
            return datetime.datetime.strptime(date_str, fmt)
        except:
            continue
    return None

class Calcurse:
    def __init__(self, datadir, confdir, calendar_file=None):
        self.datadir = os.path.abspath(datadir)
        self.confdir = os.path.abspath(confdir)
        self.calendar_file = calendar_file or os.path.join(self.datadir, 'apts')
        self.todo_file = os.path.join(self.datadir, 'todo')
        self.pid_file = os.path.join(self.datadir, '.calcurse.pid')

        os.makedirs(self.datadir, exist_ok=True)
        os.makedirs(self.confdir, exist_ok=True)

        self.appointments = []
        self.todos = []
        self.load_data()

    def load_data(self):
        if os.path.exists(self.calendar_file):
            with open(self.calendar_file, 'r') as f:
                for line in f:
                    self.parse_apt_line(line.strip())
        if os.path.exists(self.todo_file):
            with open(self.todo_file, 'r') as f:
                for line in f:
                    self.parse_todo_line(line.strip())

    def parse_apt_line(self, line):
        if not line: return
        m = re.match(r'^(\d{2}/\d{2}/\d{4}) @ (\d{2}:\d{2}) -> (\d{2}/\d{2}/\d{4}) @ (\d{2}:\d{2})(.*)\|(.*)$', line)
        if m:
            start_date_str, start_time_str, end_date_str, end_time_str, extra, desc = m.groups()
            recurrence = None
            if '{' in extra:
                recur_match = re.search(r'\{(.*?)\}', extra)
                if recur_match: recurrence = recur_match.group(1)
            self.appointments.append({
                'type': 'appointment',
                'start': datetime.datetime.strptime(f"{start_date_str} {start_time_str}", "%m/%d/%Y %H:%M"),
                'end': datetime.datetime.strptime(f"{end_date_str} {end_time_str}", "%m/%d/%Y %H:%M"),
                'recurrence': recurrence,
                'description': desc.strip(),
                'raw': line
            })
        else:
            m = re.match(r'^(\d{2}/\d{2}/\d{4}) \[(\d+)\](.*)$', line)
            if m:
                date_str, item_id, rest = m.groups()
                recurrence = None
                desc = rest
                if '{' in rest:
                    recur_match = re.search(r'\{(.*?)\}', rest)
                    if recur_match:
                        recurrence = recur_match.group(1)
                        desc = desc.replace(recur_match.group(0), '')
                self.appointments.append({
                    'type': 'event',
                    'date': datetime.datetime.strptime(date_str, "%m/%d/%Y"),
                    'id': int(item_id),
                    'recurrence': recurrence,
                    'description': desc.strip(),
                    'raw': line
                })

    def parse_todo_line(self, line):
        if not line: return
        m = re.match(r'^\[(\d+)\](.*)$', line)
        if m:
            priority, desc = m.groups()
            self.todos.append({
                'priority': int(priority),
                'description': desc.strip(),
                'raw': line
            })

    def is_occurring_on(self, item, day):
        if item['type'] == 'appointment':
            start_day = item['start'].replace(hour=0, minute=0, second=0, microsecond=0)
            if item['recurrence']:
                period, end_date_str = item['recurrence'].split(' -> ')
                end_date = datetime.datetime.strptime(end_date_str, "%m/%d/%Y")
                if day < start_day or day > end_date: return False
                num, unit = int(period[:-1]), period[-1]
                if unit == 'D': return (day - start_day).days % num == 0
                if unit == 'W': return (day - start_day).days % (num * 7) == 0
                if unit == 'M':
                    if day.day != start_day.day: return False
                    months = (day.year - start_day.year) * 12 + (day.month - start_day.month)
                    return months % num == 0
                if unit == 'Y':
                    if (day.month, day.day) != (start_day.month, start_day.day): return False
                    return (day.year - start_day.year) % num == 0
            return start_day == day
        elif item['type'] == 'event':
            start_day = item['date']
            if item['recurrence']:
                period, end_date_str = item['recurrence'].split(' -> ')
                end_date = datetime.datetime.strptime(end_date_str, "%m/%d/%Y")
                if day < start_day or day > end_date: return False
                num, unit = int(period[:-1]), period[-1]
                if unit == 'D': return (day - start_day).days % num == 0
                if unit == 'W': return (day - start_day).days % (num * 7) == 0
                if unit == 'M':
                    if day.day != start_day.day: return False
                    months = (day.year - start_day.year) * 12 + (day.month - start_day.month)
                    return months % num == 0
                if unit == 'Y':
                    if (day.month, day.day) != (start_day.month, start_day.day): return False
                    return (day.year - start_day.year) % num == 0
            return start_day == day
        return False

    def get_items_for_day(self, day):
        day_items = []
        for apt in self.appointments:
            if self.is_occurring_on(apt, day):
                day_items.append(apt)
        return day_items

def run_tui(cal):
    if os.path.exists(cal.pid_file):
        print("\nWARNING: it seems that another calcurse instance is already running.")
        print(f"If this is not the case, please remove the following lock file: \n\"{cal.pid_file}\"\nand restart calcurse.")
        sys.exit(1)

    with open(cal.pid_file, 'w') as f: f.write(str(os.getpid()))

    def tui(stdscr):
        curses.curs_set(0)
        stdscr.clear()
        while True:
            stdscr.addstr(0, 0, "calcurse TUI - Press 'q' to quit (Simplified Reimplementation)")
            stdscr.refresh()
            c = stdscr.getch()
            if c == ord('q'):
                break
    try:
        curses.wrapper(tui)
    finally:
        if os.path.exists(cal.pid_file): os.remove(cal.pid_file)

def main():
    args = sys.argv[1:]

    datadir = os.path.expanduser('~/.local/share/calcurse')
    confdir = os.path.expanduser('~/.config/calcurse')
    if os.path.exists(os.path.expanduser('~/.calcurse')):
        datadir = confdir = os.path.expanduser('~/.calcurse')

    calendar_file = None
    i = 0
    while i < len(args):
        if args[i] == '-D': datadir = args[i+1]; i += 2
        elif args[i] == '-C': confdir = args[i+1]; i += 2
        elif args[i] == '-c': calendar_file = args[i+1]; i += 2
        else: i += 1

    cal = Calcurse(datadir, confdir, calendar_file)

    if '--status' in args:
        if os.path.exists(cal.pid_file):
            with open(cal.pid_file, 'r') as f: pid = f.read().strip()
            print(f"calcurse is running (pid {pid})")
        else:
            print("calcurse is not running")
        return

    if not args:
        run_tui(cal)
        return

    if '-v' in args or '--version' in args:
        print(VERSION); return
    if '-h' in args or '--help' in args:
        print(HELP_TEXT); return

    if '-n' in args or '--next' in args:
        now = datetime.datetime.now()
        upcoming = []
        for a in cal.appointments:
            if a['type'] == 'appointment':
                for day_offset in range(2):
                    day = now.replace(hour=0, minute=0, second=0, microsecond=0) + datetime.timedelta(days=day_offset)
                    if cal.is_occurring_on(a, day):
                        occ_start = a['start'].replace(year=day.year, month=day.month, day=day.day)
                        if occ_start > now and occ_start <= now + datetime.timedelta(hours=24):
                            upcoming.append((occ_start, a['description']))
        if upcoming:
            upcoming.sort(); next_apt = upcoming[0]; diff = next_apt[0] - now
            h, m = divmod(diff.seconds // 60, 60)
            print(f"next appointment:\n   [{h:02d}:{m:02d}] {next_apt[1]}")
        return

    if '-G' in args or '--grep' in args:
        ftype = None
        if '--filter-type' in args: ftype = args[args.index('--filter-type') + 1]
        if ftype in (None, 'todo'):
            for t in sorted(cal.todos, key=lambda x: (x['priority'], x['description'])): print(t['raw'])
        if ftype in (None, 'apt'):
            for a in cal.appointments: print(a['raw'])
        return

    # Simplified export
    if '-x' in args or any(a.startswith('-x') for a in args):
        print("BEGIN:VCALENDAR\nVERSION:2.0\nPRODID:-//calcurse//NONSGML v4.8.2//EN\nEND:VCALENDAR")
        return

    start_date = None; query_days = 0
    if '-a' in args: start_date = datetime.datetime.now().replace(hour=0, minute=0, second=0, microsecond=0); query_days = 1
    elif '-d' in args:
        val = args[args.index('-d')+1]
        start_date = parse_date(val)
        if start_date is None:
            try: query_days, start_date = int(val), datetime.datetime.now().replace(hour=0, minute=0, second=0, microsecond=0)
            except: print(f"args.c: 550: invalid date: {val}"); sys.exit(1)
        else: query_days = 1
    elif '-Q' in args or '--query' in args:
        start_date = datetime.datetime.now().replace(hour=0, minute=0, second=0, microsecond=0)
        end_date = None
        if '--from' in args: start_date = parse_date(args[args.index('--from')+1])
        if '--to' in args: end_date = parse_date(args[args.index('--to')+1])
        if '--days' in args: query_days = int(args[args.index('--days')+1])
        if end_date: query_days = (end_date - start_date).days + 1
        elif query_days == 0: query_days = 1

    if start_date:
        if '-Q' in args or '--query' in args:
            if cal.todos:
                print("to do:")
                for t in sorted(cal.todos, key=lambda x: (x['priority'], x['description'])): print(f"{t['priority']}. {t['description']}")
                print()
        outputs = []
        for d in range(query_days):
            day = start_date + datetime.timedelta(days=d)
            items = cal.get_items_for_day(day)
            if items:
                day_out = [day.strftime("%m/%d/%y:")]
                events = sorted([i for i in items if i['type'] == 'event'], key=lambda x: (x['id'], x['description']))
                apts = sorted([i for i in items if i['type'] == 'appointment'], key=lambda x: (x['start'], x['description']))
                for e in events: day_out.append(f" * {e['description']}")
                for a in apts:
                    day_out.append(f" - {a['start'].strftime('%H:%M')} -> {a['end'].strftime('%H:%M')}")
                    day_out.append(f"\t{a['description']}")
                outputs.append("\n".join(day_out))
        if outputs: print("\n\n".join(outputs))

    for arg in args:
        if arg.startswith('-t'):
            p = int(arg[2:]) if len(arg) > 2 else None
            todos = [t for t in cal.todos if p is None or t['priority'] == p]
            if todos and not ('-Q' in args or '--query' in args): # Avoid double printing for -Q
                print("to do:")
                for t in sorted(todos, key=lambda x: (x['priority'], x['description'])): print(f"{t['priority']}. {t['description']}")

if __name__ == "__main__":
    main()
